<?php
/*
 * FICHIER : detailsarticle.php
 * RÔLE    : afficher la fiche complète d'un article sélectionné.
 */
require __DIR__.'/connexion.php';require_auth();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
$q=$bd->prepare('SELECT a.*,c.categorie,c.idcategorie FROM articles a LEFT JOIN categories c ON c.idcategorie=a.idcategorie WHERE a.idarticle=?');
$q->execute([$id?:0]);$a=$q->fetch();
if(!$a){http_response_code(404);flash('Article introuvable.','error');header('Location: galeriecategorie.php');exit;}
page_start($a['article'],'home');
?><style>.article-detail{display:grid;grid-template-columns:minmax(280px,1fr) minmax(280px,1fr);gap:28px;padding:24px}.article-detail-image{width:100%;height:360px;object-fit:cover;border-radius:12px;background:#eef0eb}.article-detail-placeholder{height:360px;border-radius:12px;background:#eef0eb;display:grid;place-items:center;color:var(--muted)}.article-detail h2{font-size:25px;margin:0 0 8px}.article-detail-description{color:var(--muted);line-height:1.6;margin:20px 0}.article-detail-meta{display:grid;grid-template-columns:1fr 1fr;gap:12px}.article-detail-meta div{background:var(--paper);border-radius:10px;padding:14px}.article-detail-meta small{display:block;color:var(--muted);margin-bottom:5px}.article-detail-meta strong{font-size:18px}.article-detail-actions{display:flex;gap:9px;margin-top:20px}@media(max-width:700px){.article-detail{grid-template-columns:1fr;padding:16px}.article-detail-image,.article-detail-placeholder{height:260px}}</style><div class="eyebrow"><a href="galeriecategorie.php?view=articles">Articles</a> / Fiche article</div><div class="heading-row"><div><h1><?=e($a['article'])?></h1><p><?=e($a['categorie']??'Sans catégorie')?></p></div><a class="btn btn-quiet" href="Ajoutearticle.php">Modifier l’article</a></div><section class="panel article-detail"><div><?php if($a['photo']):?><img class="article-detail-image" src="photos/<?=rawurlencode((string)$a['photo'])?>" alt="<?=e($a['article'])?>"><?php else:?><div class="article-detail-placeholder">Aucune photo enregistrée</div><?php endif?></div><div><h2><?=e($a['article'])?></h2><p class="article-detail-description"><?=nl2br(e($a['description']?:'Aucune description renseignée.'))?></p><div class="article-detail-meta"><div><small>Quantité disponible</small><strong><?=number_format((int)$a['quantite'],0,',',' ')?></strong></div><div><small>Prix</small><strong><?=number_format((float)$a['prix'],2,',',' ')?></strong></div></div><div class="article-detail-actions"><a class="btn btn-primary" href="Ajoutearticle.php">Modifier</a><?php if($a['idcategorie']):?><a class="btn btn-quiet" href="detailscategorie.php?id=<?=(int)$a['idcategorie']?>">Voir la catégorie</a><?php endif?></div></div></section><?php page_end();
